INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Franchise dasselbe wie ein eigenständiges Unternehmen?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzung eines Konzepts"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Modelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein Franchise?', 3, '[{"text": "Erprobtes Geschäftskonzept nutzen", "correct": true, "because": "Standardisierung"}, {"text": "Daten speichern", "correct": false, "because": "Kein IT-Fokus"}, {"text": "Netzwerke verbinden", "correct": false, "because": "Kein Netzwerkbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Franchise?', 5, '[{"text": "Markenlizenz", "correct": true, "because": "Markenrechte"}, {"text": "Franchisegebühr", "correct": true, "because": "Kosten"}, {"text": "Papierproduktion", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Franchise nutzt ein bestehendes Konzept. b) Es ist immer unabhängig vom Franchisegeber.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abhängigkeit besteht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Franchise?', 4, '[{"text": "Vertrag", "correct": false, "because": "Rechtsgrundlage"}, {"text": "Markenidentität", "correct": false, "because": "Kernmerkmal"}, {"text": "Papierfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Franchise immer eine Gebühr erfordert?', 2, '[{"text": "Ja", "correct": true, "because": "Typisch"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt der Franchisegeber?', 3, '[{"text": "Stellt Konzept bereit", "correct": true, "because": "Know-how"}, {"text": "Nur Marketing", "correct": false, "because": "Umfassender"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Franchise?', 5, '[{"text": "Bewährtes Konzept", "correct": true, "because": "Geringeres Risiko"}, {"text": "Markenbekanntheit", "correct": true, "because": "Kundenbasis"}, {"text": "Papierersparnis", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Franchise ermöglicht einheitliche Standards. b) Es ist immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gebühren üblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Franchise?', 4, '[{"text": "Franchisevertrag", "correct": false, "because": "Rechtsgrundlage"}, {"text": "Markenlizenz", "correct": false, "because": "Nutzungsrecht"}, {"text": "Eigenes Konzept", "correct": true, "because": "Vorgegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Franchise immer ein Einzelunternehmen?', 2, '[{"text": "Nein", "correct": true, "because": "Netzwerkstruktur"}, {"text": "Ja", "correct": false, "because": "Franchisesystem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele sind Franchiseunternehmen?', 4, '[{"text": "McDonald’s", "correct": true, "because": "Bekanntes Franchise"}, {"text": "Subway", "correct": true, "because": "Franchisesystem"}, {"text": "Papierladen", "correct": false, "because": "Kein Beispiel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Franchise keine Gebühren hat. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gebühren üblich"}, {"text": "Ja", "correct": false, "because": "Kosten entstehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Franchise?', 3, '[{"text": "Markenkonformität", "correct": true, "because": "Einheitlichkeit"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Franchise nutzt einheitliche Prozesse. b) Es ist völlig unabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abhängigkeit vom Geber"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Franchise?', 5, '[{"text": "Gebühren", "correct": true, "because": "Kosten"}, {"text": "Wenig Flexibilität", "correct": true, "because": "Vorgaben"}, {"text": "Hohe Unabhängigkeit", "correct": false, "because": "Abhängigkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Franchise unwichtig?', 3, '[{"text": "Vertrag", "correct": false, "because": "Rechtsgrundlage"}, {"text": "Markenidentität", "correct": false, "because": "Kernmerkmal"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Franchise eigene Innovationen einführen?', 3, '[{"text": "Nein", "correct": true, "because": "Vorgaben beachten"}, {"text": "Ja", "correct": false, "because": "Eingeschränkt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Franchise immer eine Gebühr verlangt?', 2, '[{"text": "Ja", "correct": true, "because": "Typisch"}, {"text": "Nein", "correct": false, "because": "Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für ein Franchise zentral?', 4, '[{"text": "Markenlizenz", "correct": true, "because": "Kernprinzip"}, {"text": "Eigenständigkeit", "correct": false, "because": "Abhängig"}, {"text": "Papierdokumente", "correct": false, "because": "Sekundär"}]');
